/** The empty list — the base case of {@link List}. */
export const empty = { kind: "empty" };
/**
 * Build a {@link List} from zero or more items, in order.
 *
 * @typeParam T - the element type
 * @param items - zero or more items to put in the list
 * @returns a new list containing `items` front-to-back
 *
 * @example
 * list();         // the empty list
 * list("a", "b"); // "a" → "b" → empty
 */
export function list(...items) {
    if (items.length === 0) {
        return { kind: "empty" };
    }
    const [first, ...rest] = items;
    return { kind: "items", first, rest: list(...rest) };
}
/**
 * Prepend an item to the front of a list — the TS equivalent of BSL `cons`.
 *
 * @typeParam T - the element type
 * @param item - the item to add at the front
 * @param lst - the list to add onto
 * @returns a new list with `item` followed by every element of `lst`
 *
 * @example
 * cons(1, list(2, 3)); // 1 → 2 → 3
 */
export function cons(item, lst) {
    return { kind: "items", first: item, rest: lst };
}
/**
 * Concatenate two lists: every element of `lst1` followed by every element of
 * `lst2`. Mirrors BSL `append`.
 *
 * @typeParam T - the element type
 * @param lst1 - the list whose elements come first
 * @param lst2 - the list whose elements come second
 * @returns a new list with the elements of `lst1` then those of `lst2`
 *
 * @example
 * append(list(1, 2), list(3, 4)); // 1 → 2 → 3 → 4
 *
 * @example
 * // BSL has no "add one element" primitive — wrap it in a list:
 * append(list(1, 2), list(3)); // 1 → 2 → 3
 */
export function append(lst1, lst2) {
    if (lst1.kind === "empty") {
        return lst2;
    }
    return cons(lst1.first, append(lst1.rest, lst2));
}
/**
 * Count the items in a list.
 *
 * @typeParam T - the element type
 * @param lst - the list to measure
 * @returns the number of items in `lst`
 *
 * @example
 * length(list("a", "b", "c")); // 3
 */
export function length(lst) {
    if (lst.kind === "empty") {
        return 0;
    }
    return 1 + length(lst.rest);
}
